-- Same migration as supabase/migrations/20261127064000_guide_facts.sql.
-- Prefer the supabase/migrations copy: GitHub Actions applies that folder.

-- Guide facts and visa rules for the checked tourism reference (step 1 of 3).
-- Additive only: no DROP of existing tables, no DELETE of country rows.
-- armenia, egypt, and kazakhstan stay; in_guide is set to false.
-- china and hong_kong are inserted with in_guide true, same as the other guide countries.
--
-- User zone is NOT the point formula in config/trust_config.json.
-- The seed statement below is generated by scripts/seed_guide_facts.py.
-- Merging this file to main runs .github/workflows/supabase_deploy.yml against production.
-- Do not apply it before the owner says so.

CREATE EXTENSION IF NOT EXISTS "uuid-ossp";

ALTER TABLE public.countries
    ADD COLUMN IF NOT EXISTS iso2 text,
    ADD COLUMN IF NOT EXISTS in_guide boolean NOT NULL DEFAULT false;

CREATE TABLE IF NOT EXISTS public.guide_facts (
    id uuid PRIMARY KEY DEFAULT uuid_generate_v4(),
    source_key text NOT NULL,
    country_slug text NOT NULL REFERENCES public.countries (slug),
    topic text NOT NULL,
    fact text NOT NULL,
    zone text NOT NULL CHECK (zone IN ('green', 'yellow', 'red')),
    status text NOT NULL CHECK (status IN ('active', 'outdated', 'refuted', 'gap')),
    source_url text,
    source_type text,
    source_is_official boolean NOT NULL,
    checked_at date NOT NULL,
    verified_by text,
    max_zone text CHECK (max_zone IS NULL OR max_zone IN ('green', 'yellow', 'red')),
    needs_owner_check boolean NOT NULL DEFAULT false,
    decision_needed text,
    unknown_zone text,
    instruction_id text,
    step_n integer CHECK (step_n IS NULL OR step_n > 0),
    issuer text,
    payment_system text,
    legacy jsonb,
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT guide_facts_source_key_key UNIQUE (source_key)
);

CREATE TABLE IF NOT EXISTS public.visa_rules (
    id uuid PRIMARY KEY DEFAULT uuid_generate_v4(),
    citizenship text NOT NULL DEFAULT 'RU',
    country_slug text NOT NULL REFERENCES public.countries (slug),
    rule_type text NOT NULL DEFAULT 'entry',
    country text NOT NULL,
    regime_type text NOT NULL,
    max_stay_days integer,
    day_counting text,
    allowed_purposes jsonb NOT NULL DEFAULT '[]'::jsonb,
    regime_expiry_or_trial_end date,
    user_wording_ru text NOT NULL,
    source_url text,
    source_is_official boolean NOT NULL,
    zone text NOT NULL CHECK (zone IN ('green', 'yellow', 'red')),
    status text NOT NULL CHECK (status IN ('active', 'outdated', 'refuted', 'gap')),
    last_checked date NOT NULL,
    notes text,
    disclaimer text NOT NULL DEFAULT 'Правила меняются, сверьтесь перед вылетом',
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT visa_rules_identity_key UNIQUE (citizenship, country_slug, rule_type)
);

CREATE INDEX IF NOT EXISTS idx_guide_facts_country_topic ON public.guide_facts (country_slug, topic);
CREATE INDEX IF NOT EXISTS idx_guide_facts_zone ON public.guide_facts (zone);
CREATE INDEX IF NOT EXISTS idx_guide_facts_checked_at ON public.guide_facts (checked_at);
CREATE INDEX IF NOT EXISTS idx_guide_facts_instruction_id ON public.guide_facts (instruction_id);
CREATE INDEX IF NOT EXISTS idx_visa_rules_country_slug ON public.visa_rules (country_slug);

-- Foreign keys that had no supporting index. Postgres does not index FK columns.
CREATE INDEX IF NOT EXISTS idx_card_instructions_country_id ON public.card_instructions (country_id);
CREATE INDEX IF NOT EXISTS idx_raw_posts_source_id ON public.raw_posts (source_id);
CREATE INDEX IF NOT EXISTS idx_recommendations_country_id ON public.recommendations (country_id);
CREATE INDEX IF NOT EXISTS idx_recommendations_partner_id ON public.recommendations (partner_id);
CREATE INDEX IF NOT EXISTS idx_review_fact_links_review_id ON public.review_fact_links (review_id);
CREATE INDEX IF NOT EXISTS idx_source_health_source_id ON public.source_health (source_id);
CREATE INDEX IF NOT EXISTS idx_user_country_access_country_id ON public.user_country_access (country_id);
CREATE INDEX IF NOT EXISTS idx_user_reports_fact_id ON public.user_reports (fact_id);

ALTER TABLE public.guide_facts ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.visa_rules ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS guide_facts_public_read ON public.guide_facts;
CREATE POLICY guide_facts_public_read ON public.guide_facts
    FOR SELECT
    TO anon, authenticated
    USING (true);

DROP POLICY IF EXISTS visa_rules_public_read ON public.visa_rules;
CREATE POLICY visa_rules_public_read ON public.visa_rules
    FOR SELECT
    TO anon, authenticated
    USING (true);

-- Data API: since 2026-10-30 new public tables get no default grants.
-- anon and authenticated can read. Writes stay on service_role.
-- Public SELECT includes legacy, which keeps the original object and its
-- internal source notes. source_url excludes Telegram and forum links.
-- Confirm that exposure before merging to main.
REVOKE ALL ON TABLE public.guide_facts, public.visa_rules FROM anon, authenticated;
GRANT SELECT ON TABLE public.guide_facts, public.visa_rules TO anon, authenticated;
GRANT SELECT, INSERT, UPDATE, DELETE ON TABLE public.guide_facts, public.visa_rules TO service_role;
GRANT USAGE, SELECT ON ALL SEQUENCES IN SCHEMA public TO service_role;

