('guide:hong_kong:2_pay_on_site:facts[2]', 'hong_kong', '2_pay_on_site', '«Мир» в этой стране не работает.', 'red', 'active', NULL, 'СМИ, противоречия', FALSE, '2026-10-13'::date, NULL, NULL, FALSE, NULL, 'НСПК не публикует список стран приёма в доступном виде; проверить раздел «Мир» за рубежом на mironline.ru (геоблок) — нужен российский IP.', NULL, NULL, NULL, NULL, '{"original": {"agreement": "conflict", "checked_at": "2026-10-13", "date_basis": "дата не найдена", "date_estimated": true, "date_verified": null, "decision_needed": null, "fact_type": "fact", "needs_owner_check": false, "reason": "источник media=30; свежесть ? (дата оценочная)=0; согласованность конфликт=0. Дата: дата не найдена", "refuted": false, "reports": 0, "score": 30, "score_breakdown": {"agreement": 0, "freshness": 0, "source": 30}, "source": null, "source_date": null, "source_kind": "media", "source_type": "СМИ, противоречия", "source_user_facing": true, "status": "unconfirmed", "status_derived_from": "zone", "text": "«Мир» в этой стране не работает.", "unknown_zone": "НСПК не публикует список стран приёма в доступном виде; проверить раздел «Мир» за рубежом на mironline.ru (геоблок) — нужен российский IP.", "verified_by_us": false, "zone": "red"}, "original_text": "«Мир» в этой стране не работает.", "path": "hong_kong.2_pay_on_site.facts[2]", "source_key": "guide:hong_kong:2_pay_on_site:facts[2]"}'::jsonb),
