('guide:hong_kong:5_atms:facts[0]', 'hong_kong', '5_atms', 'Карты UnionPay банков РФ: открытие 6 000 ₽ (570 ¥); обслуживание 0 ₽ при тратах/остатке от 30 000 ₽ в мес., иначе 399 ₽; снятие за рубежом 1,5% + 250 ₽ (руб.) / 2,5% + 22 ¥ (юань), в банкоматах эмитента — бесплатно.', 'green', 'active', 'https://www.atb.su/atb-karta-unionpay-lp-6/', 'official', TRUE, '2026-10-13'::date, NULL, NULL, FALSE, NULL, NULL, NULL, NULL, 'АТБ', 'UnionPay', '{"original": {"agreement": "agree", "checked_at": "2026-10-13", "date_basis": "тариф АТБ действует с 21.09.2026 (снимок 13.10.2026)", "date_estimated": false, "date_verified": "2026-09-21", "decision_needed": null, "fact_type": "fact", "needs_owner_check": false, "reason": "источник official=50; свежесть 23 дн.=30; согласованность ок=20. Дата: тариф АТБ действует с 21.09.2026 (снимок 13.10.2026)", "refuted": false, "reports": 0, "score": 100, "score_breakdown": {"agreement": 20, "freshness": 30, "source": 50}, "source": "https://www.atb.su/atb-karta-unionpay-lp-6/", "source_date": "2026-09-21", "source_kind": "official", "source_type": "official", "source_user_facing": true, "status": "confirmed", "status_derived_from": "zone", "text": "АТБ UnionPay: открытие 6 000 ₽ (570 ¥); обслуживание 0 ₽ при тратах/остатке от 30 000 ₽ в мес., иначе 399 ₽; снятие за рубежом 1,5% + 250 ₽ (руб.) / 2,5% + 22 ¥ (юань), в банкоматах АТБ — бесплатно.", "unknown_zone": null, "verified_by_us": false, "zone": "green"}, "original_text": "АТБ UnionPay: открытие 6 000 ₽ (570 ¥); обслуживание 0 ₽ при тратах/остатке от 30 000 ₽ в мес., иначе 399 ₽; снятие за рубежом 1,5% + 250 ₽ (руб.) / 2,5% + 22 ¥ (юань), в банкоматах АТБ — бесплатно.", "path": "hong_kong.5_atms.facts[0]", "source_key": "guide:hong_kong:5_atms:facts[0]"}'::jsonb),
