('guide:turkey:5_atms:facts[0]', 'turkey', '5_atms', 'Карты UnionPay банков РФ: открытие 6 000 ₽ (570 ¥); обслуживание 0 ₽ при тратах/остатке от 30 000 ₽ в мес., иначе 399 ₽; снятие за рубежом 1,5% + 250 ₽ (руб.) / 2,5% + 22 ¥ (юань), в банкоматах эмитента — бесплатно.', 'green', 'active', 'https://www.atb.su/atb-karta-unionpay-lp-6/', 'official', TRUE, '2026-10-13'::date, NULL, NULL, FALSE, NULL, NULL, NULL, NULL, 'АТБ', 'UnionPay', '{"original": {"agreement": "agree", "checked_at": "2026-10-13", "date_basis": "тариф АТБ действует с 21.09.2026 (снимок 13.10.2026)", "date_estimated": false, "date_verified": "2026-09-21", "decision_needed": null, "fact_type": "fact", "needs_owner_check": false, "reason": "источник official=50; свежесть 23 дн.=30; согласованность ок=20. Дата: тариф АТБ действует с 21.09.2026 (снимок 13.10.2026)", "refuted": false, "reports": 0, "score": 100, "score_breakdown": {"agreement": 20, "freshness": 30, "source": 50}, "source": "https://www.atb.su/atb-karta-unionpay-lp-6/", "source_date": "2026-09-21", "source_kind": "official", "source_type": "official", "source_user_facing": true, "status": "confirmed", "status_derived_from": "zone", "text": "АТБ UnionPay: открытие 6 000 ₽ (570 ¥); обслуживание 0 ₽ при тратах/остатке от 30 000 ₽ в мес., иначе 399 ₽; снятие за рубежом 1,5% + 250 ₽ (руб.) / 2,5% + 22 ¥ (юань), в банкоматах АТБ — бесплатно.", "unknown_zone": null, "verified_by_us": false, "zone": "green"}, "original_text": "АТБ UnionPay: открытие 6 000 ₽ (570 ¥); обслуживание 0 ₽ при тратах/остатке от 30 000 ₽ в мес., иначе 399 ₽; снятие за рубежом 1,5% + 250 ₽ (руб.) / 2,5% + 22 ¥ (юань), в банкоматах АТБ — бесплатно.", "path": "turkey.5_atms.facts[0]", "source_key": "guide:turkey:5_atms:facts[0]"}'::jsonb),
('guide:turkey:5_atms:facts[1]', 'turkey', '5_atms', 'Карты UnionPay банков РФ: первая рублёвая карта бесплатно, следующие 4 500 ₽, валютная 380 ¥; снятие за рубежом 2%, мин. 299 ₽.', 'green', 'active', 'https://www.rshb.ru/natural/debetcards/unionpay-cash', 'official', TRUE, '2026-10-13'::date, NULL, NULL, FALSE, NULL, NULL, NULL, NULL, 'РСХБ', 'UnionPay', '{"original": {"agreement": "agree", "checked_at": "2026-10-13", "date_basis": "наш снимок официальной страницы", "date_estimated": false, "date_verified": "2026-10-13", "decision_needed": null, "fact_type": "fact", "needs_owner_check": false, "reason": "источник official=50; свежесть 1 дн.=30; согласованность ок=20. Дата: наш снимок официальной страницы", "refuted": false, "reports": 0, "score": 100, "score_breakdown": {"agreement": 20, "freshness": 30, "source": 50}, "source": "https://www.rshb.ru/natural/debetcards/unionpay-cash", "source_date": "2026-10-13", "source_kind": "official", "source_type": "official", "source_user_facing": true, "status": "confirmed", "status_derived_from": "zone", "text": "РСХБ UnionPay: первая рублёвая карта бесплатно, следующие 4 500 ₽, валютная 380 ¥; снятие за рубежом 2%, мин. 299 ₽.", "unknown_zone": null, "verified_by_us": false, "zone": "green"}, "original_text": "РСХБ UnionPay: первая рублёвая карта бесплатно, следующие 4 500 ₽, валютная 380 ¥; снятие за рубежом 2%, мин. 299 ₽.", "path": "turkey.5_atms.facts[1]", "source_key": "guide:turkey:5_atms:facts[1]"}'::jsonb),
('guide:turkey:5_atms:facts[2]', 'turkey', '5_atms', 'UnionPay для карт РФ: лимит снятия 50 000 ¥/день, 500 000 ¥/год.', 'green', 'active', 'https://www.rshb.ru/', 'official', TRUE, '2026-10-13'::date, NULL, NULL, FALSE, NULL, NULL, NULL, NULL, NULL, NULL, '{"original": {"agreement": "agree", "checked_at": "2026-10-13", "date_basis": "наш снимок PDF; дата документа не указана", "date_estimated": true, "date_verified": "2026-10-13", "decision_needed": null, "fact_type": "fact", "needs_owner_check": false, "reason": "источник official=50; свежесть 1 дн. (дата оценочная)=30; согласованность ок=20. Дата: наш снимок PDF; дата документа не указана", "refuted": false, "reports": 0, "score": 100, "score_breakdown": {"agreement": 20, "freshness": 30, "source": 50}, "source": "https://www.rshb.ru/ (PDF «Информация о доступности сети приёма карт UnionPay в мире»)", "source_date": "2026-10-13", "source_kind": "official", "source_type": "official", "source_user_facing": true, "status": "confirmed", "status_derived_from": "zone", "text": "UnionPay для карт РФ: лимит снятия 50 000 ¥/день, 500 000 ¥/год.", "unknown_zone": null, "verified_by_us": false, "zone": "green"}, "original_text": "UnionPay для карт РФ: лимит снятия 50 000 ¥/день, 500 000 ¥/год.", "path": "turkey.5_atms.facts[2]", "source_key": "guide:turkey:5_atms:facts[2]"}'::jsonb),
