('guide:turkey:5_atms:facts[4]', 'turkey', '5_atms', 'UnionPay РФ в банкоматах VakıfBank/Ziraat/Halkbank без комиссии турецкого банка.', 'yellow', 'active', NULL, 'репозиторий; ссылки ведут на общие страницы банков, не подтверждают', FALSE, '2026-10-13'::date, NULL, NULL, FALSE, NULL, 'Нужны 2 отчёта ≤30 дней.', NULL, NULL, NULL, NULL, '{"original": {"agreement": "agree", "checked_at": "2026-10-13", "date_basis": "TURKEY_DATA 12–13.09.2026", "date_estimated": false, "date_verified": "2026-09-13", "decision_needed": null, "fact_type": "fact", "needs_owner_check": false, "reason": "источник traveler×1=15; свежесть 31 дн.=15; согласованность ок=20. Дата: TURKEY_DATA 12–13.09.2026", "refuted": false, "reports": 1, "score": 50, "score_breakdown": {"agreement": 20, "freshness": 15, "source": 15}, "source": null, "source_date": "2026-09-13", "source_kind": "traveler", "source_type": "репозиторий; ссылки ведут на общие страницы банков, не подтверждают", "source_user_facing": false, "status": "unconfirmed", "status_derived_from": "zone", "text": "UnionPay РФ в банкоматах VakıfBank/Ziraat/Halkbank без комиссии турецкого банка.", "unknown_zone": "Нужны 2 отчёта ≤30 дней.", "verified_by_us": false, "zone": "yellow"}, "original_text": "UnionPay РФ в банкоматах VakıfBank/Ziraat/Halkbank без комиссии турецкого банка.", "path": "turkey.5_atms.facts[4]", "source_key": "guide:turkey:5_atms:facts[4]"}'::jsonb),
('guide:turkey:5_atms:facts[5]', 'turkey', '5_atms', 'UnionPay банка РФ снимает лиры в VakıfBank без комиссии (так указано в TURKEY_DATA).', 'red', 'refuted', NULL, 'репозиторий', FALSE, '2026-10-13'::date, NULL, NULL, FALSE, 'Удалить Газпромбанк из TURKEY_DATA?', NULL, NULL, NULL, 'Газпромбанк', 'UnionPay', '{"original": {"agreement": "agree", "checked_at": "2026-10-13", "claim_origin": "repo", "date_basis": "TURKEY_DATA (репозиторий)", "date_estimated": true, "date_verified": "2026-09-12", "decision_needed": "Удалить Газпромбанк из TURKEY_DATA?", "fact_type": "fact", "needs_owner_check": false, "reason": "источник traveler×1=15; свежесть 32 дн. (дата оценочная)=15; согласованность ок=20; опровергнуто → black. Дата: TURKEY_DATA (репозиторий)", "refuted": true, "reports": 1, "score": 50, "score_breakdown": {"agreement": 20, "freshness": 15, "source": 15}, "source": null, "source_date": "2026-09-12", "source_kind": "traveler", "source_type": "репозиторий", "source_user_facing": false, "status": "outdated_or_refuted", "status_derived_from": "zone", "text": "UnionPay Газпромбанка снимает лиры в VakıfBank без комиссии (так указано в TURKEY_DATA).", "unknown_zone": null, "verified_by_us": false, "zone": "black"}, "original_text": "UnionPay Газпромбанка снимает лиры в VakıfBank без комиссии (так указано в TURKEY_DATA).", "path": "turkey.5_atms.facts[5]", "source_key": "guide:turkey:5_atms:facts[5]"}'::jsonb),
('guide:turkey:5_atms:facts[6]', 'turkey', '5_atms', 'Банк РФ под санкциями США; его карты UnionPay за рубежом, по данным СМИ, не обслуживаются. Из российских UnionPay за рубежом работают банки РФ.', 'yellow', 'active', 'https://t-j.ru/union-pain/', 'СМИ', FALSE, '2026-10-13'::date, NULL, NULL, FALSE, NULL, NULL, NULL, NULL, 'Газпромбанк, РСХБ, АТБ', 'UnionPay', '{"original": {"agreement": "agree", "checked_at": "2026-10-13", "date_basis": "дата статьи не определена", "date_estimated": true, "date_verified": null, "decision_needed": null, "fact_type": "fact", "needs_owner_check": false, "reason": "источник media=30; свежесть ? (дата оценочная)=0; согласованность ок=20. Дата: дата статьи не определена", "refuted": false, "reports": 0, "score": 50, "score_breakdown": {"agreement": 20, "freshness": 0, "source": 30}, "source": "https://t-j.ru/union-pain/", "source_date": null, "source_kind": "media", "source_type": "СМИ", "source_user_facing": true, "status": "unconfirmed", "status_derived_from": "zone", "text": "Газпромбанк под санкциями США; его карты UnionPay за рубежом, по данным СМИ, не обслуживаются. Из российских UnionPay за рубежом работают АТБ и РСХБ.", "unknown_zone": null, "verified_by_us": false, "zone": "yellow"}, "original_text": "Газпромбанк под санкциями США; его карты UnionPay за рубежом, по данным СМИ, не обслуживаются. Из российских UnionPay за рубежом работают АТБ и РСХБ.", "path": "turkey.5_atms.facts[6]", "source_key": "guide:turkey:5_atms:facts[6]"}'::jsonb),
('guide:turkey:6_transport:facts[0]', 'turkey', '6_transport', 'Istanbulkart — не исследовано.', 'yellow', 'gap', NULL, 'official', TRUE, '2026-10-13'::date, NULL, NULL, FALSE, NULL, 'Официальный сайт istanbulkart.istanbul.', NULL, NULL, NULL, NULL, '{"original": {"agreement": "agree", "checked_at": "2026-10-13", "date_verified": null, "decision_needed": null, "fact_type": "gap", "needs_owner_check": false, "reason": "пробел в данных, не факт", "refuted": false, "score": null, "score_breakdown": null, "source": null, "source_type": "official", "source_user_facing": false, "status": "gap", "status_derived_from": "type", "text": "Istanbulkart — не исследовано.", "unknown_zone": "Официальный сайт istanbulkart.istanbul.", "verified_by_us": false, "zone": "gap"}, "original_text": "Istanbulkart — не исследовано.", "path": "turkey.6_transport.facts[0]", "source_key": "guide:turkey:6_transport:facts[0]"}'::jsonb),
('guide:turkey:7_risks:facts[0]', 'turkey', '7_risks', 'Если банк заблокировал карту или онлайн-банк: позвонить в банк и узнать основание (115-ФЗ или база мошеннических операций ЦБ по 161-ФЗ). По 161-ФЗ — заявление об исключении из базы через банк или интернет-приёмную ЦБ. По 115-ФЗ — представить документы, банк отвечает до 7 рабочих дней, отказ обжалуется в МВК при ЦБ.', 'green', 'active', 'https://www.cbr.ru/Reception/TopicalMessage/Page/10853', 'official', TRUE, '2026-10-13'::date, NULL, NULL, FALSE, NULL, NULL, NULL, NULL, NULL, NULL, '{"original": {"agreement": "agree", "checked_at": "2026-10-13", "date_basis": "страница ЦБ, даты нет", "date_estimated": true, "date_verified": "2026-10-13", "decision_needed": null, "fact_type": "fact", "needs_owner_check": false, "reason": "источник official=50; свежесть 1 дн. (дата оценочная)=30; согласованность ок=20. Дата: страница ЦБ, даты нет", "refuted": false, "reports": 0, "score": 100, "score_breakdown": {"agreement": 20, "freshness": 30, "source": 50}, "source": "https://www.cbr.ru/Reception/TopicalMessage/Page/10853", "source_date": "2026-10-13", "source_kind": "official", "source_type": "official", "source_user_facing": true, "status": "confirmed", "status_derived_from": "zone", "text": "Если банк заблокировал карту или онлайн-банк: позвонить в банк и узнать основание (115-ФЗ или база мошеннических операций ЦБ по 161-ФЗ). По 161-ФЗ — заявление об исключении из базы через банк или интернет-приёмную ЦБ. По 115-ФЗ — представить документы, банк отвечает до 7 рабочих дней, отказ обжалуется в МВК при ЦБ.", "unknown_zone": null, "verified_by_us": false, "zone": "green"}, "original_text": "Если банк заблокировал карту или онлайн-банк: позвонить в банк и узнать основание (115-ФЗ или база мошеннических операций ЦБ по 161-ФЗ). По 161-ФЗ — заявление об исключении из базы через банк или интернет-приёмную ЦБ. По 115-ФЗ — представить документы, банк отвечает до 7 рабочих дней, отказ обжалуется в МВК при ЦБ.", "path": "turkey.7_risk