('guide:georgia:5_atms:facts[4]', 'georgia', '5_atms', 'Снятие наличных в кассе отделения: в лари до 3 000 GEL — 2% (мин. 2 GEL), свыше — 0,6%; в валюте — 0,6%.', 'yellow', 'active', NULL, 'наш опыт (07–10.2026)', FALSE, '2026-10-13'::date, 'owner', NULL, FALSE, NULL, NULL, NULL, NULL, NULL, NULL, '{"original": {"agreement": "agree", "checked_at": "2026-10-13", "date_basis": "личный опыт владельца", "date_estimated": false, "date_verified": "2026-10-13", "decision_needed": null, "fact_type": "fact", "needs_owner_check": false, "own_date": "2026-10-13", "reason": "источник internal=0; свежесть 1 дн.=30; согласованность ок=20; проверено нами → green. Дата: личный опыт владельца", "refuted": false, "reports": 0, "score": 50, "score_breakdown": {"agreement": 20, "freshness": 30, "source": 0}, "source": null, "source_date": "2026-10-13", "source_kind": "internal", "source_type": "наш опыт (07–10.2026)", "source_user_facing": false, "status": "confirmed", "status_derived_from": "zone", "text": "Снятие наличных в кассе отделения: в лари до 3 000 GEL — 2% (мин. 2 GEL), свыше — 0,6%; в валюте — 0,6%.", "unknown_zone": null, "verified_by_us": true, "zone": "green"}, "original_text": "Снятие наличных в кассе отделения: в лари до 3 000 GEL — 2% (мин. 2 GEL), свыше — 0,6%; в валюте — 0,6%.", "path": "georgia.5_atms.facts[4]", "source_key": "guide:georgia:5_atms:facts[4]"}'::jsonb),
