('guide:georgia:5_atms:facts[6]', 'georgia', '5_atms', 'Пополнение наличными через банкомат банка в стране пребывания — бесплатно.', 'yellow', 'active', NULL, 'наш опыт (07–10.2026)', FALSE, '2026-10-13'::date, 'owner', NULL, FALSE, NULL, NULL, NULL, NULL, 'TBC', NULL, '{"original": {"agreement": "agree", "checked_at": "2026-10-13", "date_basis": "личный опыт владельца", "date_estimated": false, "date_verified": "2026-10-13", "decision_needed": null, "fact_type": "fact", "needs_owner_check": false, "own_date": "2026-10-13", "reason": "источник internal=0; свежесть 1 дн.=30; согласованность ок=20; проверено нами → green. Дата: личный опыт владельца", "refuted": false, "reports": 0, "score": 50, "score_breakdown": {"agreement": 20, "freshness": 30, "source": 0}, "source": null, "source_date": "2026-10-13", "source_kind": "internal", "source_type": "наш опыт (07–10.2026)", "source_user_facing": false, "status": "confirmed", "status_derived_from": "zone", "text": "Пополнение наличными через банкомат TBC — бесплатно.", "unknown_zone": null, "verified_by_us": true, "zone": "green"}, "original_text": "Пополнение наличными через банкомат TBC — бесплатно.", "path": "georgia.5_atms.facts[6]", "source_key": "guide:georgia:5_atms:facts[6]"}'::jsonb),
('guide:georgia:5_atms:facts[7]', 'georgia', '5_atms', 'Пополнение через кассу отделения — 1/3/5 GEL (со слов владельца, не уверен).', 'yellow', 'active', NULL, 'отзыв (владелец не уверен)', FALSE, '2026-10-13'::date, NULL, NULL, TRUE, NULL, 'Официальная плата за взнос наличных в кассе TBC не найдена.', NULL, NULL, NULL, NULL, '{"original": {"agreement": "agree", "checked_at": "2026-10-13", "date_basis": "владелец, не уверен", "date_estimated": false, "date_verified": "2026-07-16", "decision_needed": null, "fact_type": "fact", "needs_owner_check": true, "reason": "источник traveler×1=15; свежесть 90 дн.=0; согласованность ок=20. Дата: владелец, не уверен", "refuted": false, "reports": 1, "score": 35, "score_breakdown": {"agreement": 20, "freshness": 0, "source": 15}, "source": null, "source_date": "2026-07-16", "source_kind": "traveler", "source_type": "отзыв (владелец не уверен)", "source_user_facing": false, "status": "unconfirmed", "status_derived_from": "zone", "text": "Пополнение через кассу отделения — 1/3/5 GEL (со слов владельца, не уверен).", "unknown_zone": "Официальная плата за взнос наличных в кассе TBC не найдена.", "verified_by_us": false, "zone": "red"}, "original_text": "Пополнение через кассу отделения — 1/3/5 GEL (со слов владельца, не уверен).", "path": "georgia.5_atms.facts[7]", "source_key": "guide:georgia:5_atms:facts[7]"}'::jsonb),
('guide:georgia:6_transport:facts[0]', 'georgia', '6_transport', 'Тбилиси: метро/автобус 1 GEL; оплата картой Metromoney или банковской картой — точная цена карты не найдена.', 'yellow', 'active', 'https://georgiantransfer.ge/georgia-travel-budget-2026-costs/', 'СМИ', FALSE, '2026-10-13'::date, NULL, NULL, FALSE, NULL, 'Официальный сайт ttc.com.ge: цена Metromoney, бесконтактная оплата картой TBC.', NULL, NULL, NULL, NULL, '{"original": {"agreement": "agree", "checked_at": "2026-10-13", "date_basis": "статья 2026, дата не определена", "date_estimated": true, "date_verified": null, "decision_needed": null, "fact_type": "fact", "needs_owner_check": false, "reason": "источник media=30; свежесть ? (дата оценочная)=0; согласованность ок=20. Дата: статья 2026, дата не определена", "refuted": false, "reports": 0, "score": 50, "score_breakdown": {"agreement": 20, "freshness": 0, "source": 30}, "source": "https://georgiantransfer.ge/georgia-travel-budget-2026-costs/", "source_date": null, "source_kind": "media", "source_type": "СМИ", "source_user_facing": true, "status": "unconfirmed", "status_derived_from": "zone", "text": "Тбилиси: метро/автобус 1 GEL; оплата картой Metromoney или банковской картой — точная цена карты не найдена.", "unknown_zone": "Официальный сайт ttc.com.ge: цена Metromoney, бесконтактная оплата картой TBC.", "verified_by_us": false, "zone": "yellow"}, "original_text": "Тбилиси: метро/автобус 1 GEL; оплата картой Metromoney или банковской картой — точная цена карты не найдена.", "path": "georgia.6_transport.facts[0]", "source_key": "guide:georgia:6_transport:facts[0]"}'::jsonb),
('guide:georgia:7_risks:facts[0]', 'georgia', '7_risks', 'Если банк заблокировал карту или онлайн-банк: позвонить в банк и узнать основание (115-ФЗ или база мошеннических операций ЦБ по 161-ФЗ). По 161-ФЗ — заявление об исключении из базы через банк или интернет-приёмную ЦБ. По 115-ФЗ — представить документы, банк отвечает до 7 рабочих дней, отказ обжалуется в МВК при ЦБ.', 'green', 'active', 'https://www.cbr.ru/Reception/TopicalMessage/Page/10853', 'official', TRUE, '2026-10-13'::date, NULL, NULL, FALSE, NULL, NULL, NULL, NULL, NULL, NULL, '{"original": {"agreement": "agree", "checked_at": "2026-10-13", "date_basis": "страница ЦБ, даты нет", "date_estimated": true, "date_verified": "2026-10-13", "decision_needed": null, "fact_type": "fact", "needs_owner_check": false, "reason": "источник official=50; свежесть 1 дн. (дата оценочная)=30; согласованность ок=20. Дата: страница ЦБ, даты нет", "refuted": false, "reports": 0, "score": 100, "score_breakdown": {"agreement": 20, "freshness": 30, "source": 50}, "source": "https://www.cbr.ru/Reception/TopicalMessage/Page/10853", "source_date": "2026-10-13", "source_kind": "official", "source_type": "official", "source_user_facing": true, "status": "confirmed", "status_derived_from": "zone", "text": "Если банк заблокировал карту или онлайн-банк: позвонить в банк и узнать основание (115-ФЗ или база мошеннических операций ЦБ по 161-ФЗ). По 161-ФЗ — заявление об исключении из базы через банк или интернет-приёмную ЦБ. По 115-ФЗ — представить документы, банк отвечает до 7 рабочих дней, отказ обжалуется в МВК при ЦБ.", "unknown_zone": null, "verified_by_us": false, "zone": "green"}, "original_text": "Если банк заблокировал карту или онлайн-банк: позвонить в банк и узнать основание (115-ФЗ или база мошеннических операций ЦБ по 161-ФЗ). По 161-ФЗ — заявление об исключении из базы через банк или интернет-приёмную ЦБ. По 115-ФЗ — представить документы, банк отвечает до 7 рабочих дней, отказ обжалуется в МВК при ЦБ.", "path": "georgia.7_risks.facts[0]", "source_key": "guide:georgia:7_risks:facts[0]"}'::jsonb)
