('step:wechat_pay:14', 'china', '3_local_wallets_cards', 'С иностранной карты: 0% до ¥200, выше — 3% со всей суммы. При возврате комиссия возвращается частично.', 'green', 'active', 'https://cs.help.wechat.com/hc/en-us/articles/11975770896271-How-to-Set-Up-International-Cards-for-Weixin-Pay', 'official', TRUE, '2026-10-13'::date, NULL, NULL, FALSE, NULL, NULL, 'wechat_pay', 14, NULL, NULL, '{"instruction_id": "wechat_pay", "original": {"agreement": "agree", "checked_at": "2026-10-13", "date_basis": "справка WeChat, даты обновления нет", "date_estimated": true, "date_verified": "2026-10-13", "decision_needed": null, "fact_type": "fact", "n": 14, "needs_owner_check": false, "reason": "источник official=50; свежесть 1 дн. (дата оценочная)=30; согласованность ок=20. Дата: справка WeChat, даты обновления нет", "refuted": false, "reports": 0, "score": 100, "score_breakdown": {"agreement": 20, "freshness": 30, "source": 50}, "source": "https://cs.help.wechat.com/hc/en-us/articles/11975770896271-How-to-Set-Up-International-Cards-for-Weixin-Pay", "source_date": "2026-10-13", "source_kind": "official", "source_type": "official", "source_user_facing": true, "stage": "6. Комиссии", "status": "confirmed", "status_derived_from": "zone", "text": "С иностранной карты: 0% до ¥200, выше — 3% со всей суммы. При возврате комиссия возвращается частично.", "unknown_zone": null, "verified_by_us": false, "zone": "green"}, "original_text": "С иностранной карты: 0% до ¥200, выше — 3% со всей суммы. При возврате комиссия возвращается частично.", "service": "WeChat Pay (Weixin Pay) — полная настройка", "source_key": "step:wechat_pay:14"}'::jsonb)
