-j.ru", "type": "independent", "url": "https://t-j.ru/georgia-card/", "verdict": "partial"}], "date_basis": "Личный опыт владельца 14–16.07.2026. Дата карточки — дата внешнего подтверждения, сверенного 2026-10-18.", "date_estimated": true, "date_verified": "2026-09-29", "decision_needed": null, "fact_type": "fact", "n": 2, "needs_owner_check": false, "official_confirmed": false, "own_date": "2026-07-16", "reason": "источник traveler=15; свежесть 19 дн.=30; согласованность ок=20. Класс bank_procedure. Личный опыт 14–16.07.2026; внешние источники сверены 2026-10-18.", "refuted": false, "reports": 1, "score": 65, "score_breakdown": {"agreement": 20, "freshness": 30, "source": 15}, "source": "https://yandex.com.ge/maps/org/tbc_bank/62876197993/reviews/", "source_date": "2026-09-29", "source_kind": "traveler", "source_type": "наш опыт (07–10.2026)", "source_user_facing": true, "stage": "0. До поездки", "status": "unconfirmed", "status_derived_from": "zone", "text": "Поставить приложение-переводчик. Обычно говорят по-грузински и по-английски; по-русски — не везде, держите переводчик.", "unknown_zone": null, "verified_by_us": false, "volatility_class": "bank_procedure", "zone": "yellow"}, "original_text": "Поставить приложение-переводчик. Обычно говорят по-грузински и по-английски; по-русски — не везде, держите переводчик.", "service": "TBC Bank (Грузия) — карта за 1–2 дня", "source_key": "step:tbc_georgia:2"}'::jsonb),
