INSERT INTO public.visa_rules (
    citizenship, country_slug, rule_type, country, regime_type, max_stay_days, day_counting, allowed_purposes, regime_expiry_or_trial_end, user_wording_ru, source_url, source_is_official, zone, status, last_checked, notes, disclaimer
) VALUES
('RU', 'china', 'entry', 'China', 'visa-free', 30, '30 календарных дней со дня, следующего за днём въезда; per entry; число въездов и суммарные дни не ограничены', '["business", "tourism", "family/friends visit", "exchange", "transit"]'::jsonb, '2027-12-31'::date, 'въезд без визы до 30 дней, действует до 31.12.2027', 'https://www.mfa.gov.cn/wjbzwfwpt/kzx/tzgg/202605/t20260520_11914502.html', TRUE, 'green', 'active', '2026-11-03'::date, 'Подтверждено МИД КНР 20.05.2026, посольством КНР в РФ и FAQ посольства (sr.china-embassy.gov.cn 26.05.2026). Работа/учёба/журналистика — нужна виза. Не выводится из правил 240ч транзита.', 'Правила меняются, сверьтесь перед вылетом'),
('RU', 'hong_kong', 'entry', 'Hong Kong', 'visa-free', 14, 'per entry', '["visit/tourism", "business visit (no employment)"]'::jsonb, NULL, 'въезд без визы до 14 дней', 'https://www.immd.gov.hk/eng/services/visas/visit-transit/visit-visa-entry-permit.html', TRUE, 'green', 'active', '2026-11-03'::date, 'Отдельный от материкового Китая режим; въезд в HK обнуляет/завершает пребывание по китайскому безвизу.', 'Правила меняются, сверьтесь перед вылетом'),
('RU', 'thailand', 'entry', 'Thailand', 'visa-free', 30, 'per entry (двустороннее соглашение РФ–Таиланд 2007)', '["tourism", "short visits"]'::jsonb, NULL, 'въезд без визы до 30 дней', 'https://moscow.thaiembassy.org/en/publicservice/revision-of-thailand-s-visa-exemption-and-visa-on-arrival-schemes', TRUE, 'green', 'active', '2026-11-03'::date, 'ИЗМЕНЕНИЕ: с 15.09.2026 60-дневный безвиз отменён; для РФ остаётся 30 дней по соглашению. Въехавшие до 15.09.2026 остаются до даты в штампе.', 'Правила меняются, сверьтесь перед вылетом'),
('RU', 'turkey', 'entry', 'Turkey', 'visa-free', 60, 'до 60 дней за въезд, не более 90 дней в любые 180', '["tourism", "business visits", "transit"]'::jsonb, NULL, 'въезд без визы до 60 дней (не более 90 за 180)', 'https://mid.ru/useful_information/information/entrance_mode/', TRUE, 'green', 'active', '2026-11-03'::date, 'Соглашение 12.05.2010 (30 дн.), решение Совмина Турции №2013/4665 — до 60 дн. с 16.05.2013. Не для журналистской деятельности.', 'Правила меняются, сверьтесь перед вылетом'),
